// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════
class bshifter_coverage extends uvm_subscriber #(bshifter_seq_item);
  `uvm_component_utils(bshifter_coverage)

  bit [7:0] cov_x;
  bit [2:0] cov_s;
  bit [7:0] cov_y;

  covergroup cg_bshifter;
    option.per_instance = 1;

    cp_x: coverpoint cov_x {
      bins zero       = {8'h00};
      bins max        = {8'hFF};
      bins msb_only   = {8'h80};
      bins lsb_only   = {8'h01};
      bins alt_01     = {8'h55};
      bins alt_10     = {8'hAA};
      bins low_range  = {[8'h02:8'h7F]};
      bins high_range = {[8'h81:8'hFE]};
    }

    cp_s: coverpoint cov_s {
      bins shift[] = {[0:7]};
    }

    cp_y: coverpoint cov_y {
      bins zero    = {8'h00};
      bins max     = {8'hFF};
      bins nonzero = {[8'h01:8'hFE]};
    }

    cx_x_s: cross cp_x, cp_s;
    cx_s_y: cross cp_s, cp_y;
  endgroup

  covergroup cg_single_bits;
    option.per_instance = 1;

    cp_x_bits: coverpoint cov_x {
      bins bit0 = {8'h01};
      bins bit1 = {8'h02};
      bins bit2 = {8'h04};
      bins bit3 = {8'h08};
      bins bit4 = {8'h10};
      bins bit5 = {8'h20};
      bins bit6 = {8'h40};
      bins bit7 = {8'h80};
    }

    cp_s_all: coverpoint cov_s {
      bins shift[] = {[0:7]};
    }

    cx_bit_shift: cross cp_x_bits, cp_s_all;
  endgroup

  function new(string name = "bshifter_coverage", uvm_component parent = null);
    super.new(name, parent);
    cg_bshifter    = new();
    cg_single_bits = new();
  endfunction

  virtual function void write(bshifter_seq_item t);
    cov_x = t.x;
    cov_s = t.s;
    cov_y = t.y;

    cg_bshifter.sample();
    cg_single_bits.sample();
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info(get_type_name(), $sformatf(
      "\n===== COVERAGE SUMMARY =====\ncg_bshifter: %.2f%%\ncg_single_bits: %.2f%%\n============================",
      cg_bshifter.get_inst_coverage(),
      cg_single_bits.get_inst_coverage()), UVM_NONE)
  endfunction
endclass

