// Top-level testbench module: instantiates DUT, creates virtual interfaces,
// generates clock, and calls run_test().

module tb_top;

  // Interface instantiation
  bshifter8 bif();

  // DUT instantiation — connect interface signals to DUT ports
  barrel_shifter_8 dut (
    .x (bif.x),
    .s (bif.s),
    .y (bif.y)
  );

  // Store virtual interface in config_db so UVM components can retrieve it
  initial begin
    uvm_config_db #(virtual bshifter8)::set(null, "*", "vif", bif);
  end

  // Start UVM test
  initial begin
    run_test("bshifter_test");
  end

  // Simulation timeout safety net
  initial begin
    #1_000_000;
    `uvm_fatal("TIMEOUT", "Simulation timed out!")
  end

  // Optional: dump waveforms
  initial begin
    $dumpfile("bshifter.vcd");
    $dumpvars(0, tb_top);
  end
endmodule

